import React from 'react';
import SimulationControls from './SimulationControls';

// Accept all the same props as SimulationControls
import type { SimulationControlsProps } from './SimulationControls';

const ScarewareHeaderContainer: React.FC<SimulationControlsProps> = (props) => {
  return (
    <div
      style={{
        width: '100%',
        position: 'relative',
        top: 0,
        left: 0,
        zIndex: 10001,
        background: 'rgba(45,45,45,0.98)',
        boxShadow: '0 2px 8px rgba(0,0,0,0.12)',
        borderBottom: '2px solid #007bff',
        padding: 0,
        margin: 0,
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'stretch',
        minHeight: 'unset',
      }}
    >
      <div style={{ width: '100%', maxWidth: 420, margin: '0 auto' }}>
        <SimulationControls {...props} />
      </div>
    </div>
  );
};

export default ScarewareHeaderContainer;
